/**
 * Enhanced AI Thinking Steps Renderer
 * Shows detailed step-by-step AI thinking process with engaging animations
 */

import React, { useState, useEffect, useRef } from 'react';
import {
  Box,
  Typography,
  LinearProgress,
  Chip,
  Fade,
  Grow,
  Card,
  CardContent,
  Stepper,
  Step,
  StepLabel,
  StepContent,
  Avatar,
  Divider
} from '@mui/material';
import {
  CheckCircle as CheckCircleIcon,
  RadioButtonUnchecked as RadioButtonUncheckedIcon,
  Psychology as BrainIcon,
  Search as SearchIcon,
  Analytics as AnalyticsIcon,
  AutoAwesome as SparkleIcon,
  DataObject as DataIcon,
  TrendingUp as TrendIcon,
  Lightbulb as InsightIcon,
  Speed as ProcessIcon
} from '@mui/icons-material';
import { motion, AnimatePresence } from 'framer-motion';
import './StreamingMessageRenderer.css';

// Enhanced thinking step icons mapping
const getStepIcon = (message, isActive, isCompleted) => {
  const iconProps = {
    sx: {
      fontSize: 20,
      color: isCompleted ? 'success.main' : isActive ? 'primary.main' : 'grey.400'
    }
  };

  if (message.includes('🔍') || message.includes('Analyzing')) return <SearchIcon {...iconProps} />;
  if (message.includes('📊') || message.includes('data')) return <DataIcon {...iconProps} />;
  if (message.includes('🧠') || message.includes('thinking')) return <BrainIcon {...iconProps} />;
  if (message.includes('📈') || message.includes('trend')) return <TrendIcon {...iconProps} />;
  if (message.includes('💡') || message.includes('insight')) return <InsightIcon {...iconProps} />;
  if (message.includes('⚡') || message.includes('processing')) return <ProcessIcon {...iconProps} />;
  if (message.includes('✨') || message.includes('generating')) return <SparkleIcon {...iconProps} />;

  return isCompleted ? <CheckCircleIcon {...iconProps} /> :
         isActive ? <RadioButtonUncheckedIcon {...iconProps} className="rotating-icon" /> :
         <RadioButtonUncheckedIcon {...iconProps} />;
};

const StreamingMessageRenderer = ({
  messages,
  timing,
  onComplete,
  analysis,
  complexity
}) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState([]);
  const [isComplete, setIsComplete] = useState(false);
  const [progress, setProgress] = useState(0);
  const [thinkingDetails, setThinkingDetails] = useState('');
  const timeoutRef = useRef(null);
  const startTimeRef = useRef(Date.now());

  // Enhanced thinking details for each step
  const getThinkingDetails = (stepIndex, message) => {
    const details = {
      0: "Parsing your question and identifying key safety concepts...",
      1: "Determining which safety modules contain relevant data...",
      2: "Establishing database connections and preparing queries...",
      3: "Executing optimized SQL queries across safety databases...",
      4: "Processing raw data and calculating key performance indicators...",
      5: "Applying AI algorithms to identify patterns and trends...",
      6: "Cross-referencing data points for comprehensive analysis...",
      7: "Generating contextual insights based on safety best practices...",
      8: "Formatting results and preparing visualizations...",
      9: "Finalizing response with actionable recommendations..."
    };

    return details[stepIndex] || "Processing your request with advanced AI algorithms...";
  };

  useEffect(() => {
    if (messages.length === 0) return;

    startTimeRef.current = Date.now();
    setCurrentStep(0);
    setCompletedSteps([]);
    setIsComplete(false);
    setProgress(0);
    setThinkingDetails('');

    const executeStep = (stepIndex) => {
      if (stepIndex >= messages.length) {
        setIsComplete(true);
        setProgress(100);
        setThinkingDetails('Analysis complete! Ready to provide insights.');
        if (onComplete) {
          setTimeout(onComplete, 800); // Slightly longer delay for better UX
        }
        return;
      }

      setCurrentStep(stepIndex);
      setThinkingDetails(getThinkingDetails(stepIndex, messages[stepIndex]));

      // Update progress
      const progressValue = ((stepIndex + 1) / messages.length) * 100;
      setProgress(progressValue);

      const stepDuration = timing[stepIndex] || 1000;

      timeoutRef.current = setTimeout(() => {
        setCompletedSteps(prev => [...prev, stepIndex]);
        executeStep(stepIndex + 1);
      }, stepDuration);
    };

    executeStep(0);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [messages, timing, onComplete]);

  const getStepColor = (stepIndex) => {
    if (completedSteps.includes(stepIndex)) return 'success.main';
    if (stepIndex === currentStep && !isComplete) return 'primary.main';
    return 'grey.500';
  };

  const getComplexityColor = (complexity) => {
    const colors = {
      'simple': 'success',
      'medium': 'warning',
      'complex': 'error',
      'cross-module': 'secondary'
    };
    return colors[complexity] || 'primary';
  };

  const formatElapsedTime = () => {
    const elapsed = Math.floor((Date.now() - startTimeRef.current) / 1000);
    return `${elapsed}s`;
  };

  const getComplexityDescription = (complexity) => {
    const descriptions = {
      'simple': 'Quick analysis of basic safety metrics',
      'medium': 'Comprehensive analysis across multiple data points',
      'complex': 'Deep analysis with cross-module correlations',
      'cross-module': 'Advanced multi-module safety assessment'
    };
    return descriptions[complexity] || 'Processing safety data';
  };

  return (
    <Card
      elevation={0}
      sx={{
        maxWidth: 500,
        background: 'linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%)',
        border: '1px solid',
        borderColor: 'divider',
        borderRadius: 3
      }}
    >
      <CardContent sx={{ p: 3 }}>
        {/* AI Thinking Header */}
        <Box sx={{ mb: 3 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
            <motion.div
              animate={{
                rotate: isComplete ? 0 : [0, 360],
                scale: [1, 1.1, 1]
              }}
              transition={{
                rotate: { duration: 2, repeat: isComplete ? 0 : Infinity, ease: "linear" },
                scale: { duration: 1.5, repeat: Infinity, ease: "easeInOut" }
              }}
            >
              <Avatar sx={{
                bgcolor: 'primary.main',
                width: 40,
                height: 40,
                boxShadow: '0 4px 12px rgba(25, 118, 210, 0.3)'
              }}>
                <BrainIcon />
              </Avatar>
            </motion.div>
            <Box>
              <Typography variant="h6" sx={{ fontWeight: 600, color: 'primary.main' }}>
                AI Safety Assistant
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {getComplexityDescription(complexity)}
              </Typography>
            </Box>
          </Box>

          {/* Analysis Tags */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', mb: 2 }}>
            <Chip
              label={analysis?.questionType || 'Processing'}
              size="small"
              color="primary"
              variant="outlined"
              sx={{ fontWeight: 500 }}
            />
            <Chip
              label={complexity}
              size="small"
              color={getComplexityColor(complexity)}
              variant="filled"
              sx={{ fontWeight: 500 }}
            />
            {!isComplete && (
              <Chip
                label={formatElapsedTime()}
                size="small"
                variant="outlined"
                sx={{ fontWeight: 500 }}
              />
            )}
          </Box>
        </Box>

        {/* Enhanced Progress Section */}
        <Box sx={{ mb: 3 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
            <Typography variant="body2" sx={{ fontWeight: 600, color: 'text.primary' }}>
              Thinking Process
            </Typography>
            <Typography variant="caption" sx={{
              fontWeight: 600,
              color: isComplete ? 'success.main' : 'primary.main',
              fontSize: '0.8rem'
            }}>
              {Math.round(progress)}% Complete
            </Typography>
          </Box>

          <LinearProgress
            variant="determinate"
            value={progress}
            sx={{
              height: 8,
              borderRadius: 4,
              backgroundColor: 'grey.200',
              mb: 1,
              '& .MuiLinearProgress-bar': {
                borderRadius: 4,
                background: isComplete
                  ? 'linear-gradient(90deg, #4caf50 0%, #66bb6a 100%)'
                  : 'linear-gradient(90deg, #1976d2 0%, #42a5f5 100%)',
                transition: 'all 0.4s ease-in-out'
              }
            }}
          />

          <Typography variant="caption" color="text.secondary" sx={{ fontStyle: 'italic' }}>
            Step {Math.min(currentStep + 1, messages.length)} of {messages.length}
          </Typography>
        </Box>

        <Divider sx={{ mb: 3 }} />

        {/* Enhanced Thinking Steps */}
        <Box sx={{ minHeight: 250 }}>
          <Stepper orientation="vertical" sx={{ '& .MuiStepConnector-line': { minHeight: 20 } }}>
            {messages.map((message, index) => (
              <Step key={index} active={index <= currentStep} completed={completedSteps.includes(index)}>
                <StepLabel
                  StepIconComponent={() => getStepIcon(message, index === currentStep && !isComplete, completedSteps.includes(index))}
                  sx={{
                    '& .MuiStepLabel-label': {
                      fontWeight: index === currentStep && !isComplete ? 600 : 400,
                      color: getStepColor(index),
                      fontSize: '0.95rem'
                    }
                  }}
                >
                  <motion.div
                    initial={{ opacity: 0, x: -20 }}
                    animate={{
                      opacity: index <= currentStep ? 1 : 0.3,
                      x: index <= currentStep ? 0 : -20
                    }}
                    transition={{ duration: 0.4, delay: index * 0.1 }}
                  >
                    {message}
                  </motion.div>
                </StepLabel>

                {/* Show thinking details for current step */}
                {index === currentStep && !isComplete && (
                  <StepContent>
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      transition={{ duration: 0.3 }}
                    >
                      <Box sx={{
                        p: 2,
                        backgroundColor: 'primary.light',
                        borderRadius: 2,
                        border: '1px solid',
                        borderColor: 'primary.main',
                        mt: 1
                      }}>
                        <Typography
                          variant="body2"
                          sx={{
                            color: 'primary.dark',
                            fontStyle: 'italic',
                            lineHeight: 1.5
                          }}
                          className="typing-animation"
                        >
                          💭 {thinkingDetails}
                        </Typography>
                      </Box>
                    </motion.div>
                  </StepContent>
                )}
              </Step>
            ))}
          </Stepper>
        </Box>

        {/* Enhanced Completion Message */}
        {isComplete && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
            <Box
              sx={{
                mt: 3,
                p: 3,
                borderRadius: 3,
                background: 'linear-gradient(135deg, #e8f5e8 0%, #f1f8e9 100%)',
                border: '2px solid',
                borderColor: 'success.main',
                display: 'flex',
                alignItems: 'center',
                gap: 2,
                boxShadow: '0 4px 12px rgba(76, 175, 80, 0.2)'
              }}
            >
              <motion.div
                animate={{ scale: [1, 1.2, 1] }}
                transition={{ duration: 0.6, ease: "easeInOut" }}
              >
                <CheckCircleIcon sx={{ color: 'success.main', fontSize: 28 }} />
              </motion.div>
              <Box>
                <Typography variant="body1" sx={{ color: 'success.dark', fontWeight: 700, mb: 0.5 }}>
                  🎉 Analysis Complete!
                </Typography>
                <Typography variant="body2" sx={{ color: 'success.dark' }}>
                  Ready to provide comprehensive safety insights and recommendations.
                </Typography>
              </Box>
            </Box>
          </motion.div>
        )}

        {/* Performance Stats */}
        {isComplete && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.5, duration: 0.3 }}
          >
            <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center', gap: 2 }}>
              <Chip
                label={`Processed in ${formatElapsedTime()}`}
                size="small"
                variant="outlined"
                sx={{ fontWeight: 500 }}
              />
              <Chip
                label={`${messages.length} steps completed`}
                size="small"
                variant="outlined"
                sx={{ fontWeight: 500 }}
              />
            </Box>
          </motion.div>
        )}

        {/* Debug info (only in development) */}
        {process.env.NODE_ENV === 'development' && (
          <Box sx={{ mt: 2, p: 1, backgroundColor: 'grey.100', borderRadius: 1 }}>
            <Typography variant="caption" color="text.secondary">
              Debug: {analysis?.questionType} | {complexity} | Module: {analysis?.detectedModule || 'current'}
            </Typography>
          </Box>
        )}
      </CardContent>
    </Card>
  );
};

export default StreamingMessageRenderer;
